var DAYL=['Pazar','Pazartesi','Salı','Çarşamba','Perşembe','Cuma','Cumartesi'];
var HOURS={0:[660,1020],1:[780,1320],2:[630,1140],3:[780,1320],4:[630,1140],5:[630,1140],6:[660,1020]};
function ist(){
  try{var parts=new Intl.DateTimeFormat('en-US',{timeZone:'Europe/Istanbul',weekday:'short',hour:'numeric',minute:'numeric',hourCycle:'h23'}).formatToParts(new Date());
    var o={};parts.forEach(function(p){o[p.type]=p.value;});
    var wd={Sun:0,Mon:1,Tue:2,Wed:3,Thu:4,Fri:5,Sat:6}[o.weekday];var h=(+o.hour)%24,m=+o.minute;
    if(wd===undefined||isNaN(h))throw 0;return {d:wd,h:h,m:m,min:h*60+m};
  }catch(e){var n=new Date();return {d:n.getDay(),h:n.getHours(),m:n.getMinutes(),min:n.getHours()*60+n.getMinutes()};}
}
function fmt(min){return String(Math.floor(min/60)).padStart(2,'0')+':'+String(min%60).padStart(2,'0');}
function openNow(t){var r=HOURS[t.d];return t.min>=r[0]&&t.min<r[1];}
function nextOpen(t){var r=HOURS[t.d];if(t.min<r[0])return L('açılış bugün ','opens today ')+fmt(r[0]);return L('açılış yarın ','opens tomorrow ')+fmt(HOURS[(t.d+1)%7][0]);}
function tick(){var t=ist();$('#clock').textContent='Lüleburgaz '+fmt(t.min)+' · '+(openNow(t)?L('açık','open'):L('kapalı','closed'));}
