function E(id,def,tag,cls){if(LANG==='en'){if(EN[id]!==undefined)def=EN[id];id=id+'@en';}var v=(texts[id]!==undefined&&texts[id]!=='')?texts[id]:def;return '<'+(tag||'span')+(cls?' class="'+cls+'"':'')+' data-t="'+id+'">'+esc(v)+'</'+(tag||'span')+'>';}
