pbody.addEventListener('keydown',function(e){if(editing&&e.key==='Enter'){e.preventDefault();e.target.blur&&e.target.blur();}});
pbody.addEventListener('paste',function(e){if(!editing)return;e.preventDefault();var t=(e.clipboardData||window.clipboardData).getData('text');document.execCommand('insertText',false,t.replace(/\s+/g,' '));});
var seen={};
function activate(g){var h=g.userData.hot,k=h.key,type=h.type||k;
  if(k==='roof'){setRoof(true);hintOff();return;}
  if(cur===g){closePanel();return;}if(cur)closePanel();
  seen[k]=1;var pin=pinEls[k];if(pin)pin.classList.add('seen');
  if(!editing){if(k==='gate'){knock();setTimeout(function(){gateTarget=1;},RM?0:420);}
    else if(k==='vest')chime();else if(type==='scooter'){honk();hop(g);}else blip(type==='palm'?560:720);}
  openPanel(g);hintOff();}

