var pinEls={},pinWrap=$('#pins'),pinHover=null;
function buildPins(){pinWrap.innerHTML='';pinEls={};hots.forEach(function(g){var h=g.userData.hot,b=document.createElement('button');b.className='pin';b.setAttribute('aria-label',hotLabel(h));b.title=hotLabel(h);if(seen[h.key])b.classList.add('seen');
  b.addEventListener('click',function(e){e.stopPropagation();activate(g);});b.addEventListener('mouseenter',function(){pinHover=g;});b.addEventListener('mouseleave',function(){pinHover=null;});pinWrap.appendChild(b);pinEls[h.key]=b;});}

/* ---------- persistence: shared db when available, browser storage otherwise ---------- */
var DBREF=null,canWrite=false,localMode=false,lastSaved='',saveTimer=0,saving=Promise.resolve(),undo=[],pendingRemote=null;
var LSKEY='bahce-maketi-v1';
function serialize(){return {items:items.map(function(i){return {id:i.id,type:i.type,x:+i.x.toFixed(3),z:+i.z.toFixed(3),r:+i.r.toFixed(3),s:+i.s.toFixed(3)};}),texts:texts,v:1};}
function sig(st){return JSON.stringify({items:st.items,texts:st.texts});}
function applyState(st){items=sanitize(st&&st.items&&st.items.length?st.items:DEFAULT);texts={};var tx=st&&st.texts;if(tx&&typeof tx==='object')Object.keys(tx).forEach(function(k){if(typeof tx[k]==='string'&&k.length<40)texts[k]=tx[k].slice(0,400);});rebuildProps();committedState=JSON.stringify(serialize());if(cur)openPanel(cur);}
function setStat(s){$('#edStat').textContent=s;}
var committedState=null;
function changed(isText){clearTimeout(saveTimer);saveTimer=setTimeout(commit,isText?900:350);setStat('değişti…');}
function commit(){var st=serialize(),j=sig(st),now=JSON.stringify(st);if(committedState&&sig(JSON.parse(committedState))!==j){undo.push(committedState);if(undo.length>40)undo.shift();}committedState=now;
  $('#edUndo').disabled=!undo.length;if(j===lastSaved){setStat('kaydedildi ✓');return;}lastSaved=j;
  if(DBREF&&canWrite){setStat('kaydediliyor…');saving=saving.then(function(){return DBREF.set(st);}).then(function(){if(lastSaved===j)setStat('kaydedildi ✓');},function(e){setStat(e&&e.code==='quota_exceeded'?'kayıt alanı dolu':'kaydedilemedi — tekrar deneyin');lastSaved='';});}
  else{try{localStorage.setItem(LSKEY,JSON.stringify(st));setStat('bu tarayıcıya kaydedildi ✓');}catch(e){setStat('kaydedilemedi');}}}
// initial: local copy for offline preview, then the shared store
applyState(window.__MAKET_STATE||null);

/* ---------- editor ---------- */
var editing=false,selected=null,ring=null;
ring=new THREE.Mesh(new THREE.RingGeometry(0.92,1.0,48),new THREE.MeshBasicMaterial({color:0xa94b26,transparent:true,opacity:0.9,depthWrite:false}));ring.rotation.x=-Math.PI/2;ring.visible=false;D.add(ring);
var ringIn=new THREE.Mesh(new THREE.CircleGeometry(0.92,48),new THREE.MeshBasicMaterial({color:0xa94b26,transparent:true,opacity:0.12,depthWrite:false}));ringIn.rotation.x=-Math.PI/2;ring.add(ringIn);ringIn.rotation.x=0;
var palette=$('#palette');
PALETTE.forEach(function(t){var b=document.createElement('button');b.textContent='+ '+TYPES[t].l;b.addEventListener('click',function(){addItem(t);palette.hidden=true;});palette.appendChild(b);});
function itemById(id){for(var i=0;i<items.length;i++)if(items[i].id===id)return items[i];return null;}
function select(id){selected=id;var it=id&&itemById(id);
  $('#edSel').textContent=it?TYPES[it.type].l:'Bir nesne seçin';
  document.querySelectorAll('#ed [data-a]').forEach(function(b){var a=b.getAttribute('data-a');b.disabled=!it||(a==='del'&&TYPES[it.type].person!==undefined)||(a==='dup'&&TYPES[it.type].person!==undefined)||(a==='info'&&!TYPES[it.type].hot);});
  ring.visible=!!it&&editing;}
function addItem(type){var c=camTarget();var it={id:type+'_'+Math.random().toString(36).slice(2,8),type:type,x:clamp(c.x+rnd(-.5,.5),IXmin,IXmax),z:clamp(c.z+rnd(-.5,.5),IZmin,IZmax),r:0,s:1};items.push(it);rebuildProps();select(it.id);changed();blip(700);}
function camTarget(){return {x:tgt.x,z:tgt.z+3};}
function act(a){var it=selected&&itemById(selected);if(!it)return;var g=propByItem[it.id];
  if(a==='rl')it.r+=Math.PI/12;if(a==='rr')it.r-=Math.PI/12;if(a==='sm')it.s=clamp(it.s/1.1,0.4,2.5);if(a==='sp')it.s=clamp(it.s*1.1,0.4,2.5);
  if(a==='del'){items=items.filter(function(x){return x!==it;});rebuildProps();select(null);changed();blip(380);return;}
  if(a==='dup'){var n={id:it.type+'_'+Math.random().toString(36).slice(2,8),type:it.type,x:clamp(it.x+0.8,IXmin,IXmax),z:clamp(it.z+0.8,IZmin,IZmax),r:it.r,s:it.s};items.push(n);rebuildProps();select(n.id);changed();return;}
  if(a==='info'){if(g&&g.userData.hot)activate(g);return;}
  if(g)placeProp(g,it);changed();}
document.querySelectorAll('#ed [data-a]').forEach(function(b){b.addEventListener('click',function(){act(b.getAttribute('data-a'));});});
$('#edAdd').addEventListener('click',function(){palette.hidden=!palette.hidden;});
$('#edUndo').addEventListener('click',function(){if(!undo.length)return;var s=JSON.parse(undo.pop());applyState(s);select(null);clearTimeout(saveTimer);commitNoUndo();});
function commitNoUndo(){var st=serialize(),j=sig(st);$('#edUndo').disabled=!undo.length;if(j===lastSaved)return;lastSaved=j;if(DBREF&&canWrite){setStat('kaydediliyor…');saving=saving.then(function(){return DBREF.set(st);}).then(function(){setStat('kaydedildi ✓');},function(){setStat('kaydedilemedi');lastSaved='';});}else{try{localStorage.setItem(LSKEY,JSON.stringify(st));setStat('bu tarayıcıya kaydedildi ✓');}catch(e){}}}
var resetArm=0;
$('#edReset').addEventListener('click',function(){var b=this;if(!resetArm){resetArm=1;b.textContent='Emin misiniz? Tekrar basın';setTimeout(function(){resetArm=0;b.textContent='Sıfırla';},3200);return;}
  resetArm=0;b.textContent='Sıfırla';if(committedState)undo.push(committedState);applyState({items:DEFAULT,texts:{}});select(null);commitNoUndo();});
function setEditing(on){editing=on;document.body.classList.toggle('editing',on);$('#ed').hidden=!on;$('#editBtn').textContent=on?'Düzenleniyor':'Düzenle';palette.hidden=true;
  if(!on){select(null);ring.visible=false;clearTimeout(saveTimer);commit();}else{select(selected);setStat(localMode?'önizleme · bu tarayıcıya kaydedilir':'');$('#edUndo').disabled=!undo.length;}
  if(cur)openPanel(cur);}
