if(false)setTimeout(function(){if(!$('#editBtn').hidden){setEditing(true);select('scooter');}},600);
$('#edDone').addEventListener('click',function(){setEditing(false);closePanel();});
addEventListener('keydown',function(e){if(e.key==='Escape'&&menuOpen){setMenu(false);return;}if(e.key==='Escape'&&pageOpen){goHome();return;}if(e.key==='Escape'){if(!palette.hidden)palette.hidden=true;else closePanel();}
  if(!editing||(document.activeElement&&document.activeElement.isContentEditable))return;
  if(e.key==='q'||e.key==='Q')act('rl');else if(e.key==='e'||e.key==='E')act('rr');else if(e.key==='Delete'||e.key==='Backspace')act('del');else if(e.key==='+'||e.key==='=')act('sp');else if(e.key==='-')act('sm');
  else if((e.ctrlKey||e.metaKey)&&e.key==='z'){e.preventDefault();$('#edUndo').click();}});

/* ---------- input ---------- */
var canvas=renderer.domElement,ray=new THREE.Raycaster(),ndc=new THREE.Vector2(),needRay=false,hover=null,pointers={},dragging=false,downX=0,downY=0,lastX=0,lastY=0,pinchD=0,isMouse=true,curEl=$('#cur'),px=0,py=0;
var dragItem=null,dragOff=new THREE.Vector2(),dragMoved=false,groundPlane=new THREE.Plane(V3(0,1,0),0),gp=new THREE.Vector3();
function hintOff(){$('#hint').classList.add('off');}
function setNDC(x,y){ndc.set(x/vw*2-1,-(y/vh)*2+1);}
function pick(){ray.setFromCamera(ndc,camera);var hits=ray.intersectObjects(D.children,true);for(var i=0;i<hits.length;i++){var o=hits[i].object;if(o===ring||o===ringIn)continue;while(o&&o!==D){if(o.userData.hot)return o;o=o.parent;}return null;}return null;}
function pickProp(){ray.setFromCamera(ndc,camera);var hits=ray.intersectObjects(PROPS.children,true);for(var i=0;i<hits.length;i++){var o=hits[i].object;while(o&&o.parent!==PROPS)o=o.parent;if(o&&o.userData.item)return o;}return null;}
function groundAt(x,y){setNDC(x,y);ray.setFromCamera(ndc,camera);var p=ray.ray.intersectPlane(groundPlane,gp);if(!p)return null;return D.worldToLocal(p.clone());}
canvas.addEventListener('pointerdown',function(e){canvas.setPointerCapture&&canvas.setPointerCapture(e.pointerId);pointers[e.pointerId]={x:e.clientX,y:e.clientY};isMouse=e.pointerType==='mouse';
  var ids=Object.keys(pointers);
  if(ids.length===1){downX=lastX=e.clientX;downY=lastY=e.clientY;dragging=false;dragItem=null;dragMoved=false;
    if(editing){setNDC(e.clientX,e.clientY);var pg=pickProp();if(pg){dragItem=pg.userData.item;select(dragItem.id);var gpt=groundAt(e.clientX,e.clientY);if(gpt)dragOff.set(dragItem.x-gpt.x,dragItem.z-gpt.z);palette.hidden=true;}}}
  else if(ids.length===2){dragItem=null;var a=pointers[ids[0]],b=pointers[ids[1]];pinchD=Math.hypot(a.x-b.x,a.y-b.y);dragging=true;}
  lastInteract=T;V.vy=V.vp=0;});
canvas.addEventListener('pointermove',function(e){isMouse=e.pointerType==='mouse';px=e.clientX;py=e.clientY;
  if(isMouse){mx=e.clientX/vw*2-1;my=e.clientY/vh*2-1;}
  setNDC(e.clientX,e.clientY);needRay=true;
  if(!pointers[e.pointerId])return;pointers[e.pointerId]={x:e.clientX,y:e.clientY};
  var ids=Object.keys(pointers);
  if(ids.length===2){var a=pointers[ids[0]],b=pointers[ids[1]],d=Math.hypot(a.x-b.x,a.y-b.y);if(pinchD>0)V.tz=clamp(V.tz*pinchD/d,LIM.z0,LIM.z1);pinchD=d;lastInteract=T;return;}
  if(dragItem){if(!dragMoved&&Math.hypot(e.clientX-downX,e.clientY-downY)<4)return;dragMoved=true;var gpt=groundAt(e.clientX,e.clientY);if(gpt){dragItem.x=clamp(gpt.x+dragOff.x,IXmin,IXmax);dragItem.z=clamp(gpt.z+dragOff.y,IZmin,IZmax);var g=propByItem[dragItem.id];if(g)placeProp(g,dragItem);}lastInteract=T;return;}
  var dx=e.clientX-lastX,dy=e.clientY-lastY;lastX=e.clientX;lastY=e.clientY;
  if(!dragging&&Math.hypot(e.clientX-downX,e.clientY-downY)>6){dragging=true;hintOff();}
  if(dragging){V.ty-=dx*0.006;V.tp+=dy*0.004;V.vy=-dx*0.003;V.vp=dy*0.002;lastInteract=T;}});
function up(e){if(!pointers[e.pointerId])return;var wasDrag=dragging;delete pointers[e.pointerId];
  if(Object.keys(pointers).length===0){
    if(dragItem){if(dragMoved){changed();}dragItem=null;pendingRemote=null;}
    else if(!wasDrag){setNDC(e.clientX,e.clientY);var g=pick();
      if(editing){var pg=pickProp();if(pg)select(pg.userData.item.id);else{select(null);if(g&&staticHots.indexOf(g)>=0)activate(g);else if(cur)closePanel();}}
      else{if(g)activate(g);else if(cur)closePanel();}}
    dragging=false;pinchD=0;}
  else{var ids=Object.keys(pointers);lastX=pointers[ids[0]].x;lastY=pointers[ids[0]].y;}
  lastInteract=T;}
canvas.addEventListener('pointerup',up);canvas.addEventListener('pointercancel',function(e){delete pointers[e.pointerId];dragging=false;if(dragItem){dragItem=null;}});
canvas.addEventListener('pointerleave',function(e){if(e.pointerType==='mouse'){hover=null;mx=my=0;needRay=false;}});
canvas.addEventListener('wheel',function(e){e.preventDefault();V.tz=clamp(V.tz*(1+e.deltaY*0.0012),LIM.z0,LIM.z1);lastInteract=T;},{passive:false});

