var PAGES=[{"k":"hakkimizda","at":"vest","tr":"Klinik girişi","en":"Clinic entrance"},{"k":"ekibimiz","at":"p0","tr":"Bahçedeki ekip","en":"The team, in the garden"},{"k":"tedaviler","at":"palm","tr":"Palmiyenin altı","en":"Under the palm"},{"k":"rehber","at":"pergola","tr":"Hasır gölgelik","en":"The straw shade"},{"k":"kariyer","at":"win","tr":"Tedavi odası","en":"Treatment room"},{"k":"iletisim","at":"gate","tr":"Bahçe kapısı","en":"Garden gate"}];
var pageOpen=null,homeView=null,previewing=false;
function pageOf(k){for(var i=0;i<PAGES.length;i++)if(PAGES[i].k===k)return PAGES[i];return null;}
function hotFor(at){for(var i=0;i<hots.length;i++){var h=hots[i].userData.hot;if(h.key===at||h.type===at)return hots[i];}return hotMap.vest||null;}
function worldOf(g){g.updateMatrixWorld(true);return g.localToWorld(g.userData.hot.anchor.clone());}
function saveHome(){if(!homeView)homeView={ty:V.ty,tp:V.tp,tz:V.tz};}
function flyTo(g,zoom){if(!g)return;saveHome();var p=worldOf(g);tgtGoal.set(p.x,Math.max(0.6,p.y-1.2),p.z);V.tz=zoom;}
function flyHome(){tgtGoal.copy(tgtHome);if(homeView){V.ty=homeView.ty;V.tp=homeView.tp;V.tz=homeView.tz;}homeView=null;}
function markNav(k){var dh=document.getElementById('dkHome');if(dh){if(k)dh.removeAttribute('aria-current');else dh.setAttribute('aria-current','page');}document.querySelectorAll('[data-pg]').forEach(function(a){if(a.dataset.pg===k)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});moveArch(null);}
var arch=$('.nv-arch'),navPlace=$('#navPlace');
function moveArch(a,show){var tn=$('#topnav');a=a||tn.querySelector('a[aria-current]');tn.querySelectorAll('a').forEach(function(x){x.classList.toggle('lit',x===a);});
  if(!a){arch.style.opacity=0;arch._at=null;navPlace.classList.remove('on');return;}
  var mid=a.offsetLeft+a.offsetWidth/2;arch.style.opacity=1;arch.style.transform='translateX('+(mid-arch.offsetWidth/2)+'px)';if(arch._at!==a){arch._at=a;arch.classList.remove('grow');void arch.offsetWidth;arch.classList.add('grow');}
  if(show){var P=pageOf(a.dataset.pg);navPlace.textContent='↳ '+(LANG==='en'?P.en:P.tr);navPlace.style.left=mid+'px';navPlace.style.setProperty('--my',(a.offsetTop+a.offsetHeight/2)+'px');navPlace.classList.add('on');}else navPlace.classList.remove('on');}
